INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','phrasal-verbs','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"phrasal-verbs","title":"Phrasal verbs: meaning and object position","level":"B2","order":55,"summary":"Learn a verb and its particle together, including whether an object can split them.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["A verb plus particle can have a new meaning","Separable transitive phrasal verbs","Pronoun objects go in the middle","Inseparable and three-part verbs"],"rules":[{"title":"A verb plus particle can have a new meaning","explanation":"A phrasal verb combines a verb with an adverbial particle such as up, out or off. Its meaning may be literal or idiomatic. Learn the whole expression in context rather than trying to assign one fixed meaning to each particle.","pattern":"**Call off** a match = cancel it.","commonMistakes":["Off does not always mean remove: in call off, it contributes to the idiomatic meaning cancel."],"examples":["In “Please turn on the lamp”, what does the phrasal verb mean in this context? → **activate the lamp**","In “Please turn off the heater”, what does the phrasal verb mean in this context? → **deactivate the heater**"],"skill":"form"},{"title":"Separable transitive phrasal verbs","explanation":"With many transitive phrasal verbs, a noun object can come after the particle or between verb and particle. The 50 expressions in this bank are practised in their separable uses. A long noun object often sounds clearer after the particle.","pattern":"Turn **the light** off. / Turn off **the light**.","commonMistakes":["Not all multi-word verbs are separable; this pattern must be learned for the specific verb and meaning."],"examples":["Replace “the lamp” with “it” in this separable phrasal verb: “Please turn on the lamp.” → **turn it on**","Replace “the heater” with “it” in this separable phrasal verb: “Please turn off the heater.” → **turn it off**"],"skill":"meaning"},{"title":"Pronoun objects go in the middle","explanation":"With a separable phrasal verb, an unstressed object pronoun normally goes between verb and particle. Use turn it off, not turn off it. The verb carries tense; the particle does not change.","pattern":"She **turned it off**.","commonMistakes":["She turned off it is not the ordinary object-pronoun order for separable turn off."],"examples":["Move the noun object between verb and particle, preserving the past tense: “They turned on the lamp.” → **They turned the lamp on.**","Move the noun object between verb and particle, preserving the past tense: “They turned off the heater.” → **They turned the heater off.**"],"skill":"contrast"},{"title":"Inseparable and three-part verbs","explanation":"Prepositional verbs such as look after keep their preposition before the object: look after her. Three-part expressions such as put up with normally keep the whole sequence before the object. Some phrasal verbs are intransitive and have no object.","pattern":"Look **after her**. / Put **up with it**. / The plane **took off**.","commonMistakes":["Take off can be intransitive for a plane departing or separable for removing clothing; meaning changes its structure."],"examples":["Keep the phrasal verb after did not: “They did not **turn** on the lamp.”","Keep the phrasal verb after did not: “They did not **turn** off the heater.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-phrasal-order"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"7f8cca28-dde7-5dd7-a2e1-461fd3a29029","topicSlug":"phrasal-verbs","level":"B2","prompt":"In “Please turn on the lamp”, what does the phrasal verb mean in this context?","choices":[{"id":"A","text":"erect the tent"},{"id":"B","text":"remove the shoes"},{"id":"C","text":"activate the lamp"},{"id":"D","text":"extinguish the fire"}],"answerId":"C","hint":"Use the **whole verb + particle**, and check its meaning against the object.","explanation":"Here **turn on** means **activate the lamp**. Learn this verb–particle combination as a unit.","keywords":["phrasal-meaning"],"skill":"phrasal-meaning","contextKey":"phrasal-verbs-1","fingerprint":"46aecd7b89792d078938e9c81ddd4c01d924b13cc614b54528e4c69fbdd3de08","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-phrasal-order"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Use the **whole verb + particle**, and check its meaning against the object.","Here **turn on** means **activate the lamp**. Learn this verb–particle combination as a unit.","Choose **activate the lamp**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"That would describe “put up the tent”, not the expression used here.","B":"That would describe “take off the shoes”, not the expression used here.","C":"Here **turn on** means **activate the lamp**. Learn this verb–particle combination as a unit.","D":"That would describe “put out the fire”, not the expression used here."}}},{"id":"f3cb0025-ea45-5595-abca-a4ba28b36c6d","topicSlug":"phrasal-verbs","level":"B2","prompt":"Replace “the lamp” with “it” in this separable phrasal verb: “Please turn on the lamp.”","choices":[{"id":"A","text":"turn it on"},{"id":"B","text":"turn on it"},{"id":"C","text":"it turn on"},{"id":"D","text":"turn it to on"}],"answerId":"A","hint":"The object is now a **pronoun**, so place it **in the middle**.","explanation":"An object pronoun goes **between the verb and particle**: turn it on.","keywords":["pronoun-placement"],"skill":"pronoun-placement","contextKey":"phrasal-verbs-1","fingerprint":"9027facd9e86413128b14df1f2933dfe79ffd388662a44e80b7e3566bc7f7dfa","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-phrasal-order"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The object is now a **pronoun**, so place it **in the middle**.","An object pronoun goes **between the verb and particle**: turn it on.","Choose **turn it on**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"An object pronoun goes **between the verb and particle**: turn it on.","B":"With this separable verb, the object pronoun must come before the particle.","C":"This puts the object pronoun before the imperative verb.","D":"To is not part of this phrasal verb."}}},{"id":"f0c5868b-1115-5c1e-a568-91f7394f2c87","topicSlug":"phrasal-verbs","level":"B2","prompt":"Move the noun object between verb and particle, preserving the past tense: “They turned on the lamp.”","choices":[{"id":"A","text":"They turned the lamp to on."},{"id":"B","text":"They on turned the lamp."},{"id":"C","text":"They turned the lamp on."},{"id":"D","text":"They the lamp turned on."}],"answerId":"C","hint":"A **noun object** can separate this verb and particle.","explanation":"This separable use permits **verb + noun object + particle** while keeping turned in the past.","keywords":["noun-object-separation"],"skill":"noun-object-separation","contextKey":"phrasal-verbs-1","fingerprint":"642548148d006742e48d84c428b9b47f59bf08802297ad4d5d7fcf83f1c34e21","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-phrasal-order"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["A **noun object** can separate this verb and particle.","This separable use permits **verb + noun object + particle** while keeping turned in the past.","Choose **They turned the lamp on.**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The added to is not part of the expression.","B":"The particle cannot precede the verb in this structure.","C":"This separable use permits **verb + noun object + particle** while keeping turned in the past.","D":"The object cannot be placed before the verb in this ordinary statement pattern."}}},{"id":"b037a2fa-b15b-53a4-ad79-92d91b93fe90","topicSlug":"phrasal-verbs","level":"B2","prompt":"Keep the phrasal verb after did not: “They did not ____ on the lamp.”","choices":[{"id":"A","text":"been turn"},{"id":"B","text":"turn"},{"id":"C","text":"to turn"},{"id":"D","text":"turns"}],"answerId":"B","hint":"Only the verb changes form; after **did not**, use its **base form**.","explanation":"After did not, the verb is base **turn**; the particle **on** stays unchanged.","keywords":["phrasal-after-did"],"skill":"phrasal-after-did","contextKey":"phrasal-verbs-1","fingerprint":"c70cac26337301aa87159351984f908d571a7093006334f71f80d21b0aa2a6cc","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-phrasal-order"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Only the verb changes form; after **did not**, use its **base form**.","After did not, the verb is base **turn**; the particle **on** stays unchanged.","Choose **turn**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Been cannot follow did to build this negative.","B":"After did not, the verb is base **turn**; the particle **on** stays unchanged.","C":"Did not takes a bare infinitive.","D":"The next verb cannot carry a third-person -s after did."}}},{"id":"54247f94-0554-5dfb-a19c-b4e050e581d6","topicSlug":"phrasal-verbs","level":"B2","prompt":"In “Please turn off the heater”, what does the phrasal verb mean in this context?","choices":[{"id":"A","text":"deactivate the heater"},{"id":"B","text":"erect the tent"},{"id":"C","text":"remove the shoes"},{"id":"D","text":"move the rubbish outside"}],"answerId":"A","hint":"Use the **whole verb + particle**, and check its meaning against the object.","explanation":"Here **turn off** means **deactivate the heater**. Learn this verb–particle combination as a unit.","keywords":["phrasal-meaning"],"skill":"phrasal-meaning","contextKey":"phrasal-verbs-2","fingerprint":"3a9e07b3ac54f574b2cf1346827b436a5c355faf9951176e81dbcda45f7af9bf","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-phrasal-order"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Use the **whole verb + particle**, and check its meaning against the object.","Here **turn off** means **deactivate the heater**. Learn this verb–particle combination as a unit.","Choose **deactivate the heater**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Here **turn off** means **deactivate the heater**. Learn this verb–particle combination as a unit.","B":"That would describe “put up the tent”, not the expression used here.","C":"That would describe “take off the shoes”, not the expression used here.","D":"That would describe “take out the rubbish”, not the expression used here."}}},{"id":"2a3cb84a-c932-5bc8-a815-84744bd71076","topicSlug":"phrasal-verbs","level":"B2","prompt":"Replace “the heater” with “it” in this separable phrasal verb: “Please turn off the heater.”","choices":[{"id":"A","text":"turn it off"},{"id":"B","text":"turn off it"},{"id":"C","text":"it turn off"},{"id":"D","text":"turn it to off"}],"answerId":"A","hint":"The object is now a **pronoun**, so place it **in the middle**.","explanation":"An object pronoun goes **between the verb and particle**: turn it off.","keywords":["pronoun-placement"],"skill":"pronoun-placement","contextKey":"phrasal-verbs-2","fingerprint":"8ca985b4bfc18fc54dbcfe3e9ff9d6ffde01213bfc1f185df6fe6dd13a01e1c4","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-phrasal-order"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The object is now a **pronoun**, so place it **in the middle**.","An object pronoun goes **between the verb and particle**: turn it off.","Choose **turn it off**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"An object pronoun goes **between the verb and particle**: turn it off.","B":"With this separable verb, the object pronoun must come before the particle.","C":"This puts the object pronoun before the imperative verb.","D":"To is not part of this phrasal verb."}}},{"id":"a279b075-1bb3-5723-a162-ef1d1ee6e4b9","topicSlug":"phrasal-verbs","level":"B2","prompt":"Move the noun object between verb and particle, preserving the past tense: “They turned off the heater.”","choices":[{"id":"A","text":"They the heater turned off."},{"id":"B","text":"They turned the heater to off."},{"id":"C","text":"They off turned the heater."},{"id":"D","text":"They turned the heater off."}],"answerId":"D","hint":"A **noun object** can separate this verb and particle.","explanation":"This separable use permits **verb + noun object + particle** while keeping turned in the past.","keywords":["noun-object-separation"],"skill":"noun-object-separation","contextKey":"phrasal-verbs-2","fingerprint":"ba4bc6c4218a8d26a6a9d8284891a7f5ad67063b0b63be8d4100bf7f94e4a393","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-phrasal-order"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["A **noun object** can separate this verb and particle.","This separable use permits **verb + noun object + particle** while keeping turned in the past.","Choose **They turned the heater off.**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The object cannot be placed before the verb in this ordinary statement pattern.","B":"The added to is not part of the expression.","C":"The particle cannot precede the verb in this structure.","D":"This separable use permits **verb + noun object + particle** while keeping turned in the past."}}},{"id":"de510182-2e63-5f8b-a080-c835e6d7d88d","topicSlug":"phrasal-verbs","level":"B2","prompt":"Keep the phrasal verb after did not: “They did not ____ off the heater.”","choices":[{"id":"A","text":"to turn"},{"id":"B","text":"turns"},{"id":"C","text":"been turn"},{"id":"D","text":"turn"}],"answerId":"D","hint":"Only the verb changes form; after **did not**, use its **base form**.","explanation":"After did not, the verb is base **turn**; the particle **off** stays unchanged.","keywords":["phrasal-after-did"],"skill":"phrasal-after-did","contextKey":"phrasal-verbs-2","fingerprint":"56b4c634651e848adb224be425584a8213da591458f92366eb44a5f6f1997308","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-phrasal-order"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Only the verb changes form; after **did not**, use its **base form**.","After did not, the verb is base **turn**; the particle **off** stays unchanged.","Choose **turn**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Did not takes a bare infinitive.","B":"The next verb cannot carry a third-person -s after did.","C":"Been cannot follow did to build this negative.","D":"After did not, the verb is base **turn**; the particle **off** stays unchanged."}}},{"id":"5eae7c8d-6df4-5fa6-a305-a3dca586fbaa","topicSlug":"phrasal-verbs","level":"B2","prompt":"In “Please turn up the radio volume”, what does the phrasal verb mean in this context?","choices":[{"id":"A","text":"remove the decorations from their raised position"},{"id":"B","text":"increase the radio volume"},{"id":"C","text":"remove the shoes"},{"id":"D","text":"move the rubbish outside"}],"answerId":"B","hint":"Use the **whole verb + particle**, and check its meaning against the object.","explanation":"Here **turn up** means **increase the radio volume**. Learn this verb–particle combination as a unit.","keywords":["phrasal-meaning"],"skill":"phrasal-meaning","contextKey":"phrasal-verbs-3","fingerprint":"2437f801f5fc44e38dc57f38716f2fd60b1e9fc8c78cc9b87a1c75268908dab5","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-phrasal-order"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Use the **whole verb + particle**, and check its meaning against the object.","Here **turn up** means **increase the radio volume**. Learn this verb–particle combination as a unit.","Choose **increase the radio volume**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"That would describe “take down the decorations”, not the expression used here.","B":"Here **turn up** means **increase the radio volume**. Learn this verb–particle combination as a unit.","C":"That would describe “take off the shoes”, not the expression used here.","D":"That would describe “take out the rubbish”, not the expression used here."}}},{"id":"6097306f-14b2-56e8-a15c-33067a9e52cf","topicSlug":"phrasal-verbs","level":"B2","prompt":"Replace “the radio volume” with “it” in this separable phrasal verb: “Please turn up the radio volume.”","choices":[{"id":"A","text":"it turn up"},{"id":"B","text":"turn it to up"},{"id":"C","text":"turn it up"},{"id":"D","text":"turn up it"}],"answerId":"C","hint":"The object is now a **pronoun**, so place it **in the middle**.","explanation":"An object pronoun goes **between the verb and particle**: turn it up.","keywords":["pronoun-placement"],"skill":"pronoun-placement","contextKey":"phrasal-verbs-3","fingerprint":"ed669dcfcf55c0fb071be6bc77834b2a7d924618479b8d64278a77d1506b86ce","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-phrasal-order"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The object is now a **pronoun**, so place it **in the middle**.","An object pronoun goes **between the verb and particle**: turn it up.","Choose **turn it up**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This puts the object pronoun before the imperative verb.","B":"To is not part of this phrasal verb.","C":"An object pronoun goes **between the verb and particle**: turn it up.","D":"With this separable verb, the object pronoun must come before the particle."}}},{"id":"b4995b6c-9b9d-5da1-a7da-a67821e075dc","topicSlug":"phrasal-verbs","level":"B2","prompt":"Move the noun object between verb and particle, preserving the past tense: “They turned up the radio volume.”","choices":[{"id":"A","text":"They turned the radio volume up."},{"id":"B","text":"They the radio volume turned up."},{"id":"C","text":"They turned the radio volume to up."},{"id":"D","text":"They up turned the radio volume."}],"answerId":"A","hint":"A **noun object** can separate this verb and particle.","explanation":"This separable use permits **verb + noun object + particle** while keeping turned in the past.","keywords":["noun-object-separation"],"skill":"noun-object-separation","contextKey":"phrasal-verbs-3","fingerprint":"0429b528f81395436a64212b659982574ff3a75b2a625f6283c20cca6a8e65c0","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-phrasal-order"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["A **noun object** can separate this verb and particle.","This separable use permits **verb + noun object + particle** while keeping turned in the past.","Choose **They turned the radio volume up.**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This separable use permits **verb + noun object + particle** while keeping turned in the past.","B":"The object cannot be placed before the verb in this ordinary statement pattern.","C":"The added to is not part of the expression.","D":"The particle cannot precede the verb in this structure."}}},{"id":"cd5060f2-479f-578c-aec5-348058b02add","topicSlug":"phrasal-verbs","level":"B2","prompt":"Keep the phrasal verb after did not: “They did not ____ up the radio volume.”","choices":[{"id":"A","text":"to turn"},{"id":"B","text":"turns"},{"id":"C","text":"been turn"},{"id":"D","text":"turn"}],"answerId":"D","hint":"Only the verb changes form; after **did not**, use its **base form**.","explanation":"After did not, the verb is base **turn**; the particle **up** stays unchanged.","keywords":["phrasal-after-did"],"skill":"phrasal-after-did","contextKey":"phrasal-verbs-3","fingerprint":"686f604fd2d58195411e857b8652abe5f8d3f86ba0e2985b4b25bb715fba1fb1","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-phrasal-order"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Only the verb changes form; after **did not**, use its **base form**.","After did not, the verb is base **turn**; the particle **up** stays unchanged.","Choose **turn**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Did not takes a bare infinitive.","B":"The next verb cannot carry a third-person -s after did.","C":"Been cannot follow did to build this negative.","D":"After did not, the verb is base **turn**; the particle **up** stays unchanged."}}},{"id":"9b610283-0c74-5efe-aef1-2d659a1624ff","topicSlug":"phrasal-verbs","level":"B2","prompt":"In “Please turn down the music”, what does the phrasal verb mean 